<?php require_once 'config.php'; if(current_user()) redirect('account.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf($_POST['csrf']??null)){ if(!rate_limit('login',8,900)){$error='Too many attempts. Please wait 15 minutes and try again.';}else{$stmt=db()->prepare('SELECT * FROM users WHERE email=? AND status="active" LIMIT 1');$stmt->execute([trim($_POST['email'])]);$user=$stmt->fetch(); if($user&&password_verify($_POST['password'],$user['password_hash'])){if(empty($user['email_verified_at'])){$error='Please verify your email before signing in.';}else{session_regenerate_id(true);$_SESSION['user']=$user;redirect('account.php');}}else{$error='Those details did not match an active account.';}}} $pageTitle='Sign in';include 'includes/header.php'; ?>
<section class="section"><div class="container" style="max-width:540px"><div class="form-card"><div class="eyebrow">Welcome back</div><h1>Sign in.</h1><p>Pick up where you left off with the farm.</p><?php if($error): ?><div class="toast-error notice"><?= e($error) ?></div><?php endif; ?><?php if(!empty($_SESSION['verification_link'])): ?><div class="notice">Local development verification link: <a class="text-link" href="<?= e($_SESSION['verification_link']) ?>">Verify your email</a></div><?php unset($_SESSION['verification_link']); endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="form-group"><label>Email</label><input class="form-control" type="email" name="email" required></div><div class="form-group"><label>Password</label><input class="form-control" type="password" name="password" required minlength="8"></div><button class="btn btn-primary">Sign in →</button></form><p style="margin-top:20px">New here? <a class="text-link" href="register.php">Create an account</a></p></div></div></section><?php include 'includes/footer.php'; ?>
